from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE
import json
import re

pptx_path = r''mss_ai_ppt_sample_assets\backend\data\templates\经典模板.pptx''
prs = Presentation(pptx_path)

placeholders_by_slide = {}

for idx, slide in enumerate(prs.slides, 1):
    slide_placeholders = []

    for shape in slide.shapes:
        # Check text frames
        if hasattr(shape, ''text_frame''):
            text = shape.text_frame.text
            tokens = re.findall(r''\{\{([^}]+)\}\}'', text)
            for token in tokens:
                if token not in [p[''token''] for p in slide_placeholders]:
                    shape_type_name = ''CHART'' if shape.shape_type == MSO_SHAPE_TYPE.CHART else \
                                     ''TABLE'' if shape.shape_type == MSO_SHAPE_TYPE.TABLE else ''TEXT''
                    slide_placeholders.append({
                        ''token'': token,
                        ''shape_type'': shape_type_name,
                        ''text_preview'': text[:100]
                    })

        # Check if it''s actually a table
        if shape.shape_type == MSO_SHAPE_TYPE.TABLE:
            for row in shape.table.rows:
                for cell in row.cells:
                    text = cell.text
                    tokens = re.findall(r''\{\{([^}]+)\}\}'', text)
                    for token in tokens:
                        if token not in [p[''token''] for p in slide_placeholders]:
                            slide_placeholders.append({
                                ''token'': token,
                                ''shape_type'': ''TABLE'',
                                ''text_preview'': text[:50]
                            })

    placeholders_by_slide[f''slide_{idx}''] = {
        ''count'': len(slide_placeholders),
        ''placeholders'': slide_placeholders
    }

print(json.dumps(placeholders_by_slide, indent=2, ensure_ascii=False))
